package cmd

import (
	"fmt"

	"github.com/spf13/cobra"
)

// shellWrappers contains the shell functions that must be sourced into the
// user's shell session so that treeman can cd into new worktrees.
//
// The pattern mirrors how direnv / zoxide work:
//   - Each shell function calls the treeman binary for all logic.
//   - The binary prints the target directory path to stdout.
//   - The wrapper captures that output and runs cd.
//   - All user-facing messages go to stderr from the binary.
const posixShellWrappers = `# TreeMan shell integration
# Generated by: treeman init %[1]s
# Add this to your ~/.%[1]src or ~/.profile:
#   eval "$(treeman init %[1]s)"

wt() {
  local _tm_dir
  _tm_dir=$(treeman create "$@") || return $?
  [ -n "$_tm_dir" ] && cd "$_tm_dir"
}

wtb() {
  local _tm_dir
  _tm_dir=$(treeman branch "$@") || return $?
  [ -n "$_tm_dir" ] && cd "$_tm_dir"
}

wtpr() {
  local _tm_dir
  _tm_dir=$(treeman review "$@") || return $?
  [ -n "$_tm_dir" ] && cd "$_tm_dir"
}

wtmr() {
  local _tm_dir
  _tm_dir=$(treeman review "$@") || return $?
  [ -n "$_tm_dir" ] && cd "$_tm_dir"
}

wts() {
  local _tm_dir
  _tm_dir=$(treeman switch "$@") || return $?
  [ -n "$_tm_dir" ] && cd "$_tm_dir"
}

wtl() {
  treeman list "$@"
}

wtc() {
  if [ "${1:-}" = "--dry-run" ]; then
    treeman clean "$@"
    return $?
  fi

  local _tm_dir
  _tm_dir=$(treeman clean "$@") || return $?
  [ -n "$_tm_dir" ] && cd "$_tm_dir"
}

wtd() {
  local _tm_dir
  _tm_dir=$(treeman delete "$@") || return $?
  [ -n "$_tm_dir" ] && cd "$_tm_dir"
}
`

const fishShellWrappers = `# TreeMan shell integration
# Generated by: treeman init fish
# Add this to your ~/.config/fish/config.fish:
#   treeman init fish | source

function wt
  set -l _tm_dir (treeman create $argv); or return $status
  test -n "$_tm_dir"; and cd "$_tm_dir"
end

function wtb
  set -l _tm_dir (treeman branch $argv); or return $status
  test -n "$_tm_dir"; and cd "$_tm_dir"
end

function wtpr
  set -l _tm_dir (treeman review $argv); or return $status
  test -n "$_tm_dir"; and cd "$_tm_dir"
end

function wtmr
  set -l _tm_dir (treeman review $argv); or return $status
  test -n "$_tm_dir"; and cd "$_tm_dir"
end

function wts
  set -l _tm_dir (treeman switch $argv); or return $status
  test -n "$_tm_dir"; and cd "$_tm_dir"
end

function wtl
  treeman list $argv
end

function wtc
  if contains -- --dry-run $argv
    treeman clean $argv
    return $status
  end

  set -l _tm_dir (treeman clean $argv); or return $status
  test -n "$_tm_dir"; and cd "$_tm_dir"
end

function wtd
  set -l _tm_dir (treeman delete $argv); or return $status
  test -n "$_tm_dir"; and cd "$_tm_dir"
end

`

func newInitCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "init <shell>",
		Short: "Print shell integration functions",
		Long: `Print the shell wrapper functions for the specified shell.

Add this to your shell configuration file:

  # bash (~/.bashrc):
  eval "$(treeman init bash)"

  # zsh (~/.zshrc):
  eval "$(treeman init zsh)"

  # fish (~/.config/fish/config.fish):
  treeman init fish | source

This defines the wt, wtb, wtpr, wtmr, wts, wtl, wtc, and wtd functions in your shell
session, enabling automatic cd into new or switched worktrees.`,
		Args:      cobra.ExactArgs(1),
		ValidArgs: []string{"bash", "zsh", "fish"},
		RunE: func(cmd *cobra.Command, args []string) error {
			shell := args[0]
			switch shell {
			case "bash", "zsh":
				fmt.Fprintf(cmd.OutOrStdout(), posixShellWrappers, shell)
				return nil
			case "fish":
				fmt.Fprint(cmd.OutOrStdout(), fishShellWrappers)
				return nil
			default:
				return fmt.Errorf("unsupported shell %q: use 'bash', 'zsh', or 'fish'", shell)
			}
		},
	}
}
